    private static final Logger logger = LoggerFactory.getLogger(OrderController.class);
    private static final Pattern SAFE_ID_PATTERN = Pattern.compile("^[a-zA-Z0-9_-]{1,64}$");
    private static final Pattern SAFE_STATUS_PATTERN = Pattern.compile("^(pending|paid|shipped|cancelled)$");

    @GetMapping("/{orderId}/status")
    public ResponseEntity<?> getOrderStatus(@PathVariable String orderId,
                                            @RequestParam(defaultValue = "pending") String status) {
        // 获取当前认证用户
        Authentication auth = SecurityContextHolder.getContext().getAuthentication();
        String username = auth.getName();

        // 防御1: 订单ID白名单正则校验
        if (!SAFE_ID_PATTERN.matcher(orderId).matches()) {
            logger.warn("Invalid order ID format from user: {}", username);
            return ResponseEntity.badRequest().body("Invalid order ID");
        }

        // 防御2: 状态参数白名单枚举校验
        if (!SAFE_STATUS_PATTERN.matcher(status).matches()) {
            logger.warn("Invalid status value from user: {} for order: {}", username, orderId);
            return ResponseEntity.badRequest().body("Invalid status");
        }

        // 防御3: 日志记录时使用经过校验的参数
