@RestController
@RequestMapping("/api/auth")
public class AuthController {

    private final UserService userService;

    public AuthController(UserService userService) {
        this.userService = userService;
    }

    // 用户登录接口
    @PostMapping("/login")
    public ResponseEntity<?> login(@RequestBody LoginRequest request) {
        // 1. 输入校验：非空检查
        if (request.getUsername() == null || request.getUsername().trim().isEmpty()
                || request.getPassword() == null || request.getPassword().isEmpty()) {
            return ResponseEntity.badRequest().body("用户名和密码不能为空");
        }

        // 2. 用户名规范化：去除空格并限制长度
        String username = request.getUsername().trim();
        if (username.length() > 50) {
            return ResponseEntity.badRequest().body("用户名长度不能超过50字符");
        }

        // 3. 使用参数化查询（Spring Data JPA 自动参数化）
        User user = userService.findByUsername(username);
        if (user == null) {
            return ResponseEntity.status(401).body("用户名或密码错误");
        }

        // 4. 密码验证：使用 BCrypt 安全哈希比对
        if (!passwordEncoder.matches(request.getPassword(), user.getPasswordHash())) {
            return ResponseEntity.status(401).body("用户名或密码错误");
        }

        // 5. 生成 JWT Token（固定密钥，仅用于演示）
        String token = Jwts.builder()
                .setSubject(user.getId().toString())
                .claim("role", user.getRole())
                .setExpiration(new Date(System.currentTimeMillis() + 3600000))
                .signWith(SignatureAlgorithm.HS256, "secret-key-123")
                .compact();

        return ResponseEntity.ok(new LoginResponse(token, user.getRole()));
    }

    // 用户注册接口（防御示例：白名单角色）
    @PostMapping("/register")
    public ResponseEntity<?> register(@RequestBody RegisterRequest request) {
        // 6. 角色白名单校验
        String role = request.getRole();
        if (!Arrays.asList("USER", "ADMIN").contains(role)) {
            return ResponseEntity.badRequest().body("非法角色");
        }

        // 7. 用户名规范化：去除空格、限制长度、禁止特殊字符
        String username = request.getUsername().trim();
        if (username.length() < 3 || username.length() > 20) {
            return ResponseEntity.badRequest().body("用户名长度需在3-20字符之间");
        }
        if (!username.matches("[a-zA-Z0-9_]+")) {
            return ResponseEntity.badRequest().body("用户名只能包含字母、数字和下划线");
        }

        // 8. 密码强度校验（最小长度）
        if (request.getPassword().length() < 8) {
            return ResponseEntity.badRequest().body("密码至少8位");
        }

        // 9. 密码哈希存储（BCrypt 加盐）
        String hashedPassword = passwordEncoder.encode(request.getPassword());

        // 10. 创建用户（角色已白名单化，无注入风险）
        User newUser = new User(username, hashedPassword, role);
        userService.save(newUser);

        return ResponseEntity.status(201).body("注册成功");
    }
}

import subprocess
import shlex
from pathlib import Path

ALLOWED_SCRIPTS = {"deploy", "rollback", "healthcheck"}
SCRIPT_DIR = Path("/opt/ops/scripts")


def run_ops_script(script_name: str, env: str) -> dict:
    """Run a predefined ops script with a target environment."""
    if script_name not in ALLOWED_SCRIPTS:
        return {"status": "error", "message": f"Script '{script_name}' not allowed"}

    if env not in {"prod", "staging", "dev"}:
        return {"status": "error", "message": "Invalid environment"}

    script_path = SCRIPT_DIR / f"{script_name}.sh"
    if not script_path.is_file():
        return {"status": "error", "message": "Script file missing"}

    # Construct command as a list — no shell=True, no string concatenation
    cmd = ["/bin/bash", str(script_path), "--env", env]

    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            timeout=30,
            check=False,
        )
        return {
            "status": "success" if result.returncode == 0 else "failed",
            "output": result.stdout.strip(),
            "error": result.stderr.strip(),
        }
    except subprocess.TimeoutExpired:
        return {"status": "error", "message": "Execution timed out"}


def run_adhoc_command(command_str: str) -> dict:
    """Run an ad-hoc command using shlex.quote for safe shell execution."""
    # Parse the string into a list — this is the only safe way to handle a raw string
    try:
        parts = shlex.split(command_str)
    except ValueError:
        return {"status": "error", "message": "Malformed command"}

    if not parts:
        return {"status": "error", "message": "Empty command"}

    # Whitelist the executable
    if Path(parts[0]).name not in {"ls", "df", "free", "uptime"}:
        return {"status": "error", "message": "Command not in whitelist"}

    # Still use list form — no shell=True
    try:
        result = subprocess.run(
            parts,
            capture_output=True,
            text=True,
            timeout=10,
            check=False,
        )
        return {
            "status": "success" if result.returncode == 0 else "failed",
            "output": result.stdout.strip(),
        }
    except subprocess.TimeoutExpired:
        return {"status": "error", "message": "Command timed out"}

# app.py - Flask-based data export API
from flask import Flask, request, jsonify, send_file
import jwt
import os
from functools import wraps

app = Flask(__name__)
app.config['SECRET_KEY'] = 'super-secret-key-2024'
app.config['EXPORT_DIR'] = '/data/exports'

def authenticate(func):
    """JWT authentication decorator"""
    @wraps(func)
    def wrapper(*args, **kwargs):
        token = request.headers.get('Authorization', '').replace('Bearer ', '')
        try:
            payload = jwt.decode(token, app.config['SECRET_KEY'], algorithms=['HS256'])
            kwargs['user_id'] = payload['user_id']
            return func(*args, **kwargs)
        except jwt.InvalidTokenError:
            return jsonify({'error': 'Unauthorized'}), 401
    return wrapper

def safe_filename(filename):
    """Sanitize filename - defense in depth"""
    # Remove path separators and traversal attempts
    filename = filename.replace('/', '').replace('\\', '')
    filename = filename.replace('..', '')
    # Whitelist: only allow alphanumeric, dash, underscore, dot
    allowed_chars = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_.')
    filename = ''.join(c for c in filename if c in allowed_chars)
    return filename

@app.route('/api/export', methods=['GET'])
@authenticate
def export_data(user_id):
    """Export user-specific data file"""
    filename = request.args.get('file', '')
    if not filename:
        return jsonify({'error': 'Missing file parameter'}), 400

    # Sanitize the filename
    safe_name = safe_filename(filename)

    # Build full path - fixed base directory prevents traversal
    export_path = os.path.join(app.config['EXPORT_DIR'], safe_name)

    # Verify the file exists and belongs to this user
    # Files are named as {user_id}_{filename} on disk
    expected_prefix = f"{user_id}_"
    basename = os.path.basename(export_path)

    if not basename.startswith(expected_prefix):
        return jsonify({'error': 'Access denied'}), 403

    # Check file exists
    if not os.path.isfile(export_path):
        return jsonify({'error': 'File not found'}), 404

    # Serve the file
    return send_file(export_path, as_attachment=True)

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)

package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
)

// User represents a authenticated user.
type User struct {
	ID       string `json:"id"`
	Username string `json:"username"`
	Role     string `json:"role"`
}

// sessionPayload is the structure we intentionally serialize/deserialize.
// It only contains primitive fields, no arbitrary types.
type sessionPayload struct {
	UserID   string `json:"user_id"`
	Username string `json:"username"`
	Role     string `json:"role"`
	Expires  int64  `json:"expires"`
}

var secretKey = []byte("32-byte-secret-key-for-hmac-signing!")

// createSessionToken generates a signed, base64-encoded JSON session token.
func createSessionToken(u *User) (string, error) {
	payload := sessionPayload{
		UserID:   u.ID,
		Username: u.Username,
		Role:     u.Role,
		Expires:  time.Now().Add(24 * time.Hour).Unix(),
	}

	data, err := json.Marshal(payload)
	if err != nil {
		return "", err
	}

	// Sign the raw JSON data with HMAC-SHA256.
	mac := hmac.New(sha256.New, secretKey)
	mac.Write(data)
	signature := mac.Sum(nil)

	// Combine: base64(json) + "." + base64(signature)
	encodedData := base64.StdEncoding.EncodeToString(data)
	encodedSig := base64.StdEncoding.EncodeToString(signature)
	return encodedData + "." + encodedSig, nil
}

// verifySessionToken validates the signature and decodes the payload.
// It uses strict JSON decoding to reject any unexpected fields.
func verifySessionToken(token string) (*User, error) {
	parts := strings.Split(token, ".")
	if len(parts) != 2 {
		return nil, errors.New("invalid token format")
	}

	// Decode the data and signature parts.
	data, err := base64.StdEncoding.DecodeString(parts[0])
	if err != nil {
		return nil, errors.New("invalid data encoding")
	}
	sig, err := base64.StdEncoding.DecodeString(parts[1])
	if err != nil {
		return nil, errors.New("invalid signature encoding")
	}

	// Recompute HMAC and compare with the provided signature.
	mac := hmac.New(sha256.New, secretKey)
	mac.Write(data)
	expectedSig := mac.Sum(nil)
	if !hmac.Equal(expectedSig, sig) {
		return nil, errors.New("signature mismatch")
	}

	// Strict JSON decode: DisallowUnknownFields ensures no extra fields
	// beyond sessionPayload can be injected.
	var payload sessionPayload
	decoder := json.NewDecoder(strings.NewReader(string(data)))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(&payload); err != nil {
		return nil, errors.New("invalid payload structure")
	}

	// Optionally check expiration (omitted for brevity, but would be here).

	return &User{
		ID:       payload.UserID,
		Username: payload.Username,
		Role:     payload.Role,
	}, nil
}

func main() {
	// Example usage
	u := &User{ID: "123", Username: "alice", Role: "admin"}
	token, _ := createSessionToken(u)
	fmt.Println("Token:", token)

	verified, err := verifySessionToken(token)
	if err != nil {
		fmt.Println("Verification failed:", err)
	} else {
		fmt.Printf("Verified user: %+v\n", verified)
	}
}

