}

static int copy_user_data(const char __user *user_data, size_t len) {
    if (!user_data || len > MAX_BUF_SIZE) {  // line 16: 长度边界检查
        return -EINVAL;
    }

    global_buf = kmalloc(MAX_BUF_SIZE, GFP_KERNEL);
    if (!global_buf) {
        return -ENOMEM;
    }

    if (copy_from_user(global_buf, user_data, len)) {  // line 24: 安全拷贝
        cleanup_buffer();
        return -EFAULT;
    }
    global_buf[len] = '\0';  // line 28: 显式终止符
    return 0;
}

static void process_data(void) {
    if (!global_buf) {
        return;
    }

    char local_buf[MAX_BUF_SIZE];
    size_t data_len = strnlen(global_buf, MAX_BUF_SIZE);  // line 38: 受限长度

    if (data_len >= MAX_BUF_SIZE) {
        cleanup_buffer();
        return;
    }

    memcpy(local_buf, global_buf, data_len + 1);  // line 45: 拷贝含终止符
    local_buf[data_len] = '\0';

    pr_info("Processed: %s\n", local_buf);
    cleanup_buffer();
}

static int __init module_init_func(void) {
    global_buf = NULL;
    return 0;
}

static void __exit module_exit_func(void) {
    cleanup_buffer();
}

